  pubw_admin_retried: ['Verification restarted', 'გადამოწმება თავიდან დაიწყო', 'Проверка перезапущена', 'Doğrulama yeniden başlatıldı', 'أُعيد بدء التحقق', 'האימות הופעל מחדש'],
  pubw_admin_failures_n: ['{{n}} with errors', 'შეცდომით: {{n}}', 'с ошибками: {{n}}', '{{n}} hatalı', '{{n}} بها أخطاء', '{{n}} עם שגיאות'],
  pubw_admin_audit: ['Audit history', 'აუდიტის ისტორია', 'История изменений', 'Denetim geçmişi', 'سجل التدقيق', 'היסטוריית ביקורת'],
  pubw_admin_audit_empty: ['No changes recorded for this portal.', 'ამ პორტალისთვის ცვლილებები არ არის აღრიცხული.', 'Для этого портала изменений нет.', 'Bu portal için kayıtlı değişiklik yok.', 'لا تغييرات مسجلة لهذه البوابة.', 'לא נרשמו שינויים לפורטל זה.'],

  /* ── Specific messages for codes that fell back to the generic sentence (2026-10-16 audit) ── */
  pubw_err_workspace_read_failed: ['Your publishing workspace could not be loaded. Please try again in a moment.', 'გამოქვეყნების სივრცე ვერ ჩაიტვირთა. სცადეთ ცოტა ხანში.', 'Не удалось загрузить раздел публикаций. Попробуйте чуть позже.', 'Yayın alanınız yüklenemedi. Biraz sonra tekrar deneyin.', 'تعذر تحميل مساحة النشر. حاول مرة أخرى بعد قليل.', 'לא ניתן היה לטעון את אזור הפרסום. נסו שוב בעוד רגע.'],
  pubw_err_listing_save_failed: ['The listing could not be saved. Your changes are still on this page — please try again.', 'განცხადება ვერ შეინახა. ცვლილებები ამ გვერდზე რჩება, სცადეთ თავიდან.', 'Не удалось сохранить объявление. Изменения остались на странице — попробуйте ещё раз.', 'İlan kaydedilemedi. Değişiklikleriniz bu sayfada duruyor — tekrar deneyin.', 'تعذر حفظ الإعلان. ما زالت تغييراتك في هذه الصفحة — حاول مرة أخرى.', 'לא ניתן היה לשמור את המודעה. השינויים עדיין בדף — נסו שוב.'],
  pubw_err_listing_update_failed: ['The listing could not be updated. Please try again.', 'განცხადება ვერ განახლდა. სცადეთ თავიდან.', 'Не удалось обновить объявление. Попробуйте ещё раз.', 'İlan güncellenemedi. Tekrar deneyin.', 'تعذر تحديث الإعلان. حاول مرة أخرى.', 'לא ניתן היה לעדכן את המודעה. נסו שוב.'],
  pubw_err_owned_record_required: ['This listing does not exist or is not yours.', 'ეს განცხადება არ არსებობს ან თქვენი არ არის.', 'Это объявление не существует или принадлежит не вам.', 'Bu ilan yok ya da size ait değil.', 'هذا الإعلان غير موجود أو ليس لك.', 'המודעה הזו לא קיימת או אינה שלכם.'],
  pubw_err_owner_required: ['Please finish setting up your HOMATCH account first.', 'ჯერ დაასრულეთ HOMATCH-ის ანგარიშის მომზადება.', 'Сначала завершите настройку аккаунта HOMATCH.', 'Önce HOMATCH hesabınızın kurulumunu tamamlayın.', 'أكمل إعداد حسابك في HOMATCH أولًا.', 'השלימו קודם את הגדרת חשבון HOMATCH.'],
  pubw_err_invalid_id: ['This link is not valid. Open the listing again from Publish to Portals.', 'ეს ბმული არასწორია. გახსენით განცხადება ხელახლა გამოქვეყნების გვერდიდან.', 'Эта ссылка недействительна. Откройте объявление заново из раздела публикаций.', 'Bu bağlantı geçersiz. İlanı Portallarda yayınla bölümünden yeniden açın.', 'هذا الرابط غير صالح. افتح الإعلان مجددًا من صفحة النشر على البوابات.', 'הקישור אינו תקין. פתחו את המודעה שוב מעמוד הפרסום בפורטלים.'],
  pubw_err_payload_too_large: ['This listing is too large to save. Shorten the descriptions and try again.', 'განცხადება შესანახად ძალიან დიდია. შეამოკლეთ აღწერები და სცადეთ თავიდან.', 'Объявление слишком большое для сохранения. Сократите описания и попробуйте снова.', 'İlan kaydetmek için çok büyük. Açıklamaları kısaltıp tekrar deneyin.', 'الإعلان أكبر من أن يُحفظ. اختصر الأوصاف وحاول مرة أخرى.', 'המודעה גדולה מכדי להישמר. קצרו את התיאורים ונסו שוב.'],
  pubw_err_invalid_status: ['That status change is not allowed. Refresh the page and try again.', 'სტატუსის ეს ცვლილება დაუშვებელია. განაახლეთ გვერდი და სცადეთ თავიდან.', 'Такое изменение статуса недопустимо. Обновите страницу и попробуйте снова.', 'Bu durum değişikliğine izin verilmiyor. Sayfayı yenileyip tekrar deneyin.', 'تغيير الحالة هذا غير مسموح. حدّث الصفحة وحاول مرة أخرى.', 'שינוי הסטטוס הזה אינו מותר. רעננו את הדף ונסו שוב.'],
